<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: no-store, private');
require_once dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/navigation.php';
function roomSettingsH(string|int|null $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$user=$_SESSION['user']??null;if(!is_array($user)||($user['role']??'')!=='admin'){http_response_code(403);exit('Nur Administratoren können Räume und Buchungsrechte verwalten.');}
$db=coachingDatabase();$token=$_SESSION['csrf_token']??'';if(!is_string($token)||strlen($token)!==64){$token=bin2hex(random_bytes(32));$_SESSION['csrf_token']=$token;}
$error='';$notice=isset($_GET['saved'])?'Die Raum- und Coach-Zuordnungen wurden gespeichert.':'';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $posted=$_POST['csrf_token']??'';$action=(string)($_POST['action']??'');
 if(!is_string($posted)||!hash_equals($token,$posted))$error='Die Anfrage ist abgelaufen. Bitte lade die Seite neu.';
 else try{
  if($action==='room'){
   $id=filter_var($_POST['id']??0,FILTER_VALIDATE_INT);$id=$id===false?0:(int)$id;
   $name=trim(is_string($_POST['name']??null)?$_POST['name']:'');$location=trim(is_string($_POST['standort']??null)?$_POST['standort']:'');$description=trim(is_string($_POST['beschreibung']??null)?$_POST['beschreibung']:'');$active=isset($_POST['aktiv'])?1:0;
   if($id<0||$name===''||strlen($name)>120||strlen($location)>190||strlen($description)>1000)throw new InvalidArgumentException('Bitte prüfe Name, Standort und Beschreibung des Raums.');
   if($id>0){$q=$db->prepare('UPDATE coaching_raeume SET name=:name,standort=:location,beschreibung=:description,aktiv=:active WHERE id=:id');$q->execute(['name'=>$name,'location'=>$location?:null,'description'=>$description?:null,'active'=>$active,'id'=>$id]);$roomId=$id;$event='raum_bearbeitet';}
   else{$q=$db->prepare('INSERT INTO coaching_raeume (name,standort,beschreibung,aktiv,erstellt_von_benutzer_id) VALUES (:name,:location,:description,:active,:admin)');$q->execute(['name'=>$name,'location'=>$location?:null,'description'=>$description?:null,'active'=>$active,'admin'=>(int)$user['id']]);$roomId=(int)$db->lastInsertId();$event='raum_angelegt';}
   $audit=$db->prepare('INSERT INTO coaching_admin_aktionen (admin_benutzer_id,aktion,ziel_typ,ziel_id) VALUES (:admin,:action,\'raum\',:target)');$audit->execute(['admin'=>(int)$user['id'],'action'=>$event,'target'=>$roomId]);
   header('Location: room-settings.php?saved=1');exit;
  }elseif($action==='permissions'){
   $roomId=filter_var($_POST['raum_id']??null,FILTER_VALIDATE_INT);$roomId=$roomId===false?0:(int)$roomId;$requested=$_POST['coach_ids']??[];if(!is_array($requested))$requested=[];
   $requested=array_values(array_unique(array_filter(array_map(static fn($v)=>filter_var($v,FILTER_VALIDATE_INT),$requested),static fn($v)=>$v!==false&&(int)$v>0)));
   $exists=$db->prepare('SELECT id FROM coaching_raeume WHERE id=:id');$exists->execute(['id'=>$roomId]);if(!$exists->fetchColumn())throw new InvalidArgumentException('Der ausgewählte Raum wurde nicht gefunden.');
   if($requested){$holders=implode(',',array_fill(0,count($requested),'?'));$valid=$db->prepare("SELECT id FROM benutzer WHERE rolle='coach' AND aktiv=1 AND id IN ($holders)");$valid->execute($requested);if(count($valid->fetchAll(PDO::FETCH_COLUMN))!==count($requested))throw new InvalidArgumentException('Mindestens ein ausgewählter Coach ist nicht aktiv oder ungültig.');}
   $db->beginTransaction();$del=$db->prepare('DELETE FROM coaching_raum_berechtigungen WHERE raum_id=:room');$del->execute(['room'=>$roomId]);$ins=$db->prepare('INSERT INTO coaching_raum_berechtigungen (raum_id,coach_benutzer_id,darf_buchen,geaendert_von_benutzer_id) VALUES (:room,:coach,1,:admin)');foreach($requested as $coachId)$ins->execute(['room'=>$roomId,'coach'=>(int)$coachId,'admin'=>(int)$user['id']]);$audit=$db->prepare('INSERT INTO coaching_admin_aktionen (admin_benutzer_id,aktion,ziel_typ,ziel_id,details) VALUES (:admin,\'raum_buchungsrechte_geaendert\',\'raum\',:target,:details)');$audit->execute(['admin'=>(int)$user['id'],'target'=>$roomId,'details'=>'Coach-Buchungsrechte aktualisiert']);$db->commit();header('Location: room-settings.php?saved=1');exit;
  }else throw new InvalidArgumentException('Unbekannte Aktion.');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof InvalidArgumentException)$error=$e->getMessage();else{error_log('Coaching Tool room settings failed: '.$e->getMessage());$error='Die Räume konnten nicht gespeichert werden. Prüfe Migration 022 und Tabellenrechte.';}}
}
$edit=null;if(isset($_GET['edit'])){$id=filter_var($_GET['edit'],FILTER_VALIDATE_INT);if($id!==false){$q=$db->prepare('SELECT * FROM coaching_raeume WHERE id=:id');$q->execute(['id'=>(int)$id]);$edit=$q->fetch(PDO::FETCH_ASSOC)?:null;}}
$rooms=$db->query('SELECT * FROM coaching_raeume ORDER BY aktiv DESC,name')->fetchAll(PDO::FETCH_ASSOC);
$coaches=$db->query("SELECT id,vorname,nachname,coach_kennung FROM benutzer WHERE rolle='coach' AND aktiv=1 ORDER BY nachname,vorname")->fetchAll(PDO::FETCH_ASSOC);
$rights=[];$q=$db->query('SELECT raum_id,coach_benutzer_id FROM coaching_raum_berechtigungen WHERE darf_buchen=1');foreach($q->fetchAll(PDO::FETCH_ASSOC) as $row)$rights[(int)$row['raum_id']][]=(int)$row['coach_benutzer_id'];
$csrf=$token;
?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Räume verwalten · Coaching Tool</title><link rel="stylesheet" href="assets/layout.css"><script src="assets/layout.js" defer></script><style>.page{max-width:1100px;margin:auto;padding:32px clamp(20px,4vw,56px) 64px}.grid{display:grid;grid-template-columns:minmax(280px,370px) 1fr;gap:18px}.card{background:#fff;border:1px solid #e3ebe5;border-radius:14px;padding:20px;margin:18px 0}.form{display:grid;gap:11px}.form input,.form textarea{padding:11px;border:1px solid #dce5df;border-radius:8px;font:inherit}.button{border:0;border-radius:8px;padding:10px 14px;background:#245c50;color:#fff;font:inherit;text-decoration:none;cursor:pointer}.secondary{background:#edf5ef;color:#245c50}.room{border-bottom:1px solid #edf1ee;padding:16px 0}.coach-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;margin:12px 0}.notice,.error{padding:12px;border-radius:8px}.notice{background:#edf5ef}.error{background:#fff3f1;color:#842f2f}.muted{color:#718078;font-size:13px}@media(max-width:820px){.grid{grid-template-columns:1fr}}</style></head><body class="has-app-sidebar"><?php renderCoachingSidebar($user,'room-settings',$csrf);?><main class="page"><h1>Räume verwalten</h1><p>Lege verfügbare Räume an und wähle pro Raum aus, welche Coaches dort buchen dürfen. Diese Verwaltung zeigt keine Klientendaten.</p><?php if($notice):?><p class="notice" role="status"><?=roomSettingsH($notice)?></p><?php endif;?><?php if($error):?><p class="error" role="alert"><?=roomSettingsH($error)?></p><?php endif;?><div class="grid"><section class="card"><h2><?=$edit?'Raum bearbeiten':'Raum anlegen'?></h2><form class="form" method="post"><input type="hidden" name="csrf_token" value="<?=roomSettingsH($csrf)?>"><input type="hidden" name="action" value="room"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>Name<input name="name" maxlength="120" required value="<?=roomSettingsH($edit['name']??'')?>"></label><label>Standort<input name="standort" maxlength="190" value="<?=roomSettingsH($edit['standort']??'')?>"></label><label>Beschreibung<textarea name="beschreibung" maxlength="1000" rows="3"><?=roomSettingsH($edit['beschreibung']??'')?></textarea></label><label><input type="checkbox" name="aktiv" value="1" <?=!$edit||((int)$edit['aktiv']===1)?'checked':''?>> Raum buchbar</label><button class="button" type="submit">Speichern</button><?php if($edit):?><a class="button secondary" href="room-settings.php">Abbrechen</a><?php endif;?></form></section><section><h2>Vorhandene Räume</h2><?php if(!$rooms):?><p>Noch keine Räume angelegt.</p><?php endif;?><?php foreach($rooms as $room):?><article class="card"><div style="display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap"><div><h3><?=roomSettingsH($room['name'])?> · <?=((int)$room['aktiv']===1?'Aktiv':'Inaktiv')?></h3><p class="muted"><?=roomSettingsH($room['standort']??'')?></p><?php if($room['beschreibung']):?><p><?=roomSettingsH($room['beschreibung'])?></p><?php endif;?></div><a class="button secondary" href="room-settings.php?edit=<?=(int)$room['id']?>">Bearbeiten</a></div><form method="post"><input type="hidden" name="csrf_token" value="<?=roomSettingsH($csrf)?>"><input type="hidden" name="action" value="permissions"><input type="hidden" name="raum_id" value="<?=(int)$room['id']?>"><strong>Buchungsberechtigte Coaches</strong><div class="coach-list"><?php foreach($coaches as $coach):$checked=in_array((int)$coach['id'],$rights[(int)$room['id']]??[],true);?><label><input type="checkbox" name="coach_ids[]" value="<?=(int)$coach['id']?>" <?=$checked?'checked':''?>> <?=roomSettingsH($coach['vorname'].' '.$coach['nachname'])?></label><?php endforeach;?></div><button class="button" type="submit">Buchungsrechte speichern</button></form></article><?php endforeach;?></section></div></main></body></html>